void Write(const char* status,const std::string& error=""){std::ofstream(output)<<nlohmann::json{{"status",status},{"error",error},{"phase",phase},{"render_frames",drawFrames},{"charge_frames",chargeFrames},{"small_hand_frames",smallFrames},{"lens_frames",lensFrames},{"shadow_warning_frames",shadowFrames},{"drop_frames",dropFrames},{"finger_rotations",fingerAngles.size()},{"native_defeats",kills},{"checks",checks}}.dump(2);}
void Check(bool ok,const char* label){if(!ok)throw std::runtime_error(label);checks.push_back(label);SPDLOG_INFO("[Handmaster QA] PASS {}",label);Write("running");}
bool Alive(const Actor* actor){for(auto& list:gPlayState->actorCtx.actorLists)for(auto* a=list.head;a;a=a->next)if(a==actor)return a->update!=nullptr;return false;}
void Next(int p){phase=p;frames=0;}
void Warp(){gSaveContext.entranceIndex=ENTR_HYRULE_FIELD_PAST_BRIDGE_SPAWN;gSaveContext.cutsceneIndex=0;gSaveContext.sceneLayer=0;gSaveContext.respawnFlag=0;gGameState->running=false;SET_NEXT_GAMESTATE(gGameState,Play_Init,PlayState);floorHand=nullptr;wallHand=nullptr;family={};}
void Camera(){auto* p=GET_PLAYER(gPlayState);gSaveContext.health=gSaveContext.healthCapacity;gSaveContext.dayTime=gSaveContext.skyboxTime=0x8000;p->invincibilityTimer=20;p->actor.world.pos=p->actor.prevPos=fixture;p->actor.speedXZ=0;p->actor.velocity={};p->actor.shape.rot.y=Math_Vec3f_Yaw(&fixture,&anchor);Vec3f at={anchor.x,anchor.y+35,anchor.z},eye={anchor.x+145,anchor.y+125,anchor.z+195};Play_CameraSetAtEye(gPlayState,CAM_ID_MAIN,&at,&eye);}
void Clear(){for(auto* a=gPlayState->actorCtx.actorLists[ACTORCAT_ENEMY].head;a;a=a->next)Actor_Kill(a);floorHand=nullptr;wallHand=nullptr;family={};}
void SpawnFloor(bool invisible=false){auto* a=Actor_Spawn(&gPlayState->actorCtx,gPlayState,ACTOR_EN_FLOORMAS,anchor.x,anchor.y,anchor.z,0,0,0,invisible?0x8000:0);Check(a&&a->update,"Native Floormaster initializes");floorHand=reinterpret_cast<EnFloormas*>(a);family={floorHand,reinterpret_cast<EnFloormas*>(a->parent),reinterpret_cast<EnFloormas*>(a->child)};Check(family[1]&&family[2]&&family[1]->actor.parent==&family[2]->actor&&family[2]->actor.child==&family[1]->actor,"Original three-member family ring initializes with two hidden siblings");for(auto* h:family)h->actor.flags|=ACTOR_FLAG_DRAW_CULLING_DISABLED|ACTOR_FLAG_UPDATE_CULLING_DISABLED;}
void SpawnWall(int type){auto* a=Actor_Spawn(&gPlayState->actorCtx,gPlayState,ACTOR_EN_WALLMAS,anchor.x,anchor.y,anchor.z,0,0,0,type);Check(a&&a->update,"Native Wallmaster initializes");wallHand=reinterpret_cast<EnWallmas*>(a);a->flags|=ACTOR_FLAG_DRAW_CULLING_DISABLED|ACTOR_FLAG_UPDATE_CULLING_DISABLED;}
Gfx* Model(Actor* actor,SkelAnime& skel,int limb,bool original=false){auto* dl=limb==25?(Gfx*)gWallmasterFingerDL:static_cast<StandardLimb*>(skel.skeleton[limb-1])->dList;if(!original)ARPG_OverrideHandmasterLimb(gPlayState,actor,limb,&dl);return dl;}
void Models(Actor* a,SkelAnime& skel){Check(skel.limbCount==25&&skel.dListCount==14,"Original 25-entry rig and fourteen visible flex matrices are retained");bool replaced=true,cached=true,palette=true,extra=true;
 for(int l=1;l<=25;++l){auto* m=Model(a,skel,l);if(l!=25&&HandmasterGeometry::MatrixIndex(l,0)<0){Check(!m,"Original hidden joint remains hidden");continue;}replaced&=m&&m!=Model(a,skel,l,true);cached&=m==Model(a,skel,l);for(int i=0;i<50000;++i){int op=m[i].words.w0>>24;if(op==G_ENDDL)break;if(op==G_MTX){auto address=m[i].words.w1;palette&=address>=0x0D000001&&address<=0x0D000001+13*sizeof(Mtx)&&(address-0x0D000001)%sizeof(Mtx)==0;if(l==25)extra=false;}}}
 Check(replaced&&cached,"All fourteen visible limbs and the separate fifth digit use cached authored geometry");Check(palette&&extra,"Skin bridges use the fourteen original matrices; the extra digit preserves its native post-draw scale without indexing the palette");
 for(auto key:{"gEnhancements.ARPG.Enabled","gEnhancements.ARPG.RemasteredEnemies"}){CVarSetInteger(key,0);bool off=true;for(int l=1;l<=25;++l)off&=Model(a,skel,l)==Model(a,skel,l,true);Check(off,"Feature gate restores all original hand geometry including the extra digit");CVarSetInteger(key,1);}
 auto eye=GET_ACTIVE_CAM(gPlayState)->eye;GET_ACTIVE_CAM(gPlayState)->eye.x+=10000;Check(Model(a,skel,2)==Model(a,skel,2,true)&&Model(a,skel,25)==Model(a,skel,25,true),"Distance fallback restores palm and extra finger together");GET_ACTIVE_CAM(gPlayState)->eye=eye;
}
void FloorDamage(EnFloormas* h,int amount,int effect){hit={};hit.toucher.dmgFlags=0x100;h->collider.info.acHitInfo=&hit;h->collider.base.ac=&GET_PLAYER(gPlayState)->actor;h->collider.base.acFlags|=AC_HIT;h->actor.colChkInfo.damage=amount;h->actor.colChkInfo.damageEffect=effect;EnFloormas_ColliderCheck(h,gPlayState);h->actor.colChkInfo.damageEffect=0;}
void WallDamage(int amount,int effect){hit={};hit.toucher.dmgFlags=0x100;wallHand->collider.info.acHitInfo=&hit;wallHand->collider.base.ac=&GET_PLAYER(gPlayState)->actor;wallHand->collider.base.acFlags|=AC_HIT;wallHand->actor.colChkInfo.damage=amount;wallHand->actor.colChkInfo.damageEffect=effect;EnWallmas_ColUpdate(wallHand,gPlayState);wallHand->actor.colChkInfo.damageEffect=0;}
void Tick(){if(phase>=98)return;try{++frames;
 if(phase==0&&frames>60&&gGameState){CVarSetInteger("gDeveloperTools.DebugSaveFileMode",2);gSaveContext.gameMode=GAMEMODE_NORMAL;gSaveContext.fileNum=0xFE;Sram_InitDebugSave();gSaveContext.fileNum=0xFF;gSaveContext.linkAge=LINK_AGE_ADULT;gARPGSave={};for(auto k:{"gEnhancements.ARPG.Enabled","gEnhancements.ARPG.RemasteredEnemies"})CVarSetInteger(k,1);for(auto k:{"gEnhancements.ARPG.Affixes","gEnhancements.ARPG.Items","gEnhancements.ARPG.Skills","gEnhancements.ARPG.Enemies","gEnhancements.ARPG.Creatures","gEnhancements.ARPG.Packs","gEnhancements.ARPG.Enchanted","gEnhancements.ARPG.RegionalWorld","gOpenWindows.ARPG","gEnhancements.RandomizedEnemies"})CVarSetInteger(k,0);SeedRng(0xFA1);Warp();Next(1);return;}
 if(gPlayState&&phase>=2&&phase<=23)Camera();
 if(phase==1&&frames>100&&gPlayState&&GameInteractor::IsPlayerInControl()){fixture=GET_PLAYER(gPlayState)->actor.world.pos;Actor* practice=nullptr;for(int i=0;i<16&&!practice;++i){GET_PLAYER(gPlayState)->actor.shape.rot.y=i*0x1000;practice=Creatures::SpawnHandmasterPractice(gPlayState,0);}Check(practice,"Practice safely places a complete floor family beside the field population");anchor=practice->world.pos;Clear();fixture={anchor.x,anchor.y,anchor.z+650};Camera();SpawnFloor();Models(&floorHand->actor,floorHand->skelAnime);Check(floorHand->actor.scale.x==.01f&&floorHand->actor.colChkInfo.health==4&&floorHand->collider.dim.radius==25&&floorHand->collider.dim.height==40,"Original large hand scale, health and cylinder remain intact");Next(2);return;}
 if(phase==2){walk|=floorHand->actionFunc==EnFloormas_BigWalk;if(frames>90){Check(walk&&fingerAngles.size()>20,"Original finger-driven walking animation runs beneath the new surfaces");fixture={floorHand->actor.world.pos.x,floorHand->actor.world.pos.y,floorHand->actor.world.pos.z+200};floorHand->actor.shape.rot.y=0;Next(3);return;}}
 if(phase==3){windup|=floorHand->actionFunc==EnFloormas_Hover;if(chargeFrames>=6){Check(windup&&floorHand->collider.base.colType==COLTYPE_HARD&&(floorHand->collider.base.acFlags&AC_HARD),"Native hover winds up into an armored charge");FloorDamage(floorHand,9,0);Check(floorHand->actor.colChkInfo.health==4,"Native green armored charge rejects incoming damage");Vec3f pos{};Vec3s rot{};Gfx* dl=nullptr;Gfx* stream=nullptr;EnFloormas_OverrideLimbDraw(gPlayState,1,&dl,&pos,&rot,floorHand,&stream);Check(pos.z==floorHand->zOffset&&floorHand->zOffset>-1600,"Original animated root offset survives the replacement callback");fixture.x+=600;Next(4);return;}}
 if(phase==4&&frames>100&&floorHand->collider.base.colType!=COLTYPE_HARD){Check(floorHand->zOffset==-1600&&floorHand->actor.gravity==-1,"Native landing restores the grounded root and vulnerable skin");FloorDamage(floorHand,1,0);Check(floorHand->actor.colChkInfo.health==3&&floorHand->actionFunc==EnFloormas_TakeDamage,"Exposed hand uses original directional damage recoil");Next(5);return;}
 if(phase==5&&frames>85){Check(floorHand->actionFunc!=EnFloormas_TakeDamage&&floorHand->actor.colChkInfo.health==3,"Nonlethal recoil recovers through the original animation");FloorDamage(floorHand,0,1);Check(floorHand->actionFunc==EnFloormas_Freeze&&floorHand->actionTimer==80,"Stun preserves the original eighty-frame freeze");Next(6);return;}
 if(phase==6&&frames>100){Check(floorHand->actionFunc!=EnFloormas_Freeze,"Stun expiry returns the original hand to motion");FloorDamage(floorHand,9,0);Next(7);return;}
 if(phase==7&&floorHand->actionFunc==EnFloormas_Split){bool split=true;for(auto* h:family)split&=h->actor.scale.x==.004f&&h->actor.colChkInfo.health==2&&h->collider.dim.radius==15&&h->collider.dim.height==24&&h->actor.draw&&!(h->collider.info.bumperFlags&BUMP_HOOKABLE);Check(split&&kills==0,"Large defeat splits into three visible native small hands with their original reduced colliders and no premature reward");Next(8);return;}
 if(phase==8&&frames>65){Check(smallFrames>40,"All three small native hand actors animate and render after splitting");for(auto* h:family){h->actor.world.pos=anchor;h->actor.speedXZ=0;}floorHand->actor.params=0x40;EnFloormas_SetupMerge(floorHand);family[1]->actor.params=family[2]->actor.params=0x20;EnFloormas_SetupSmWait(family[1]);Next(9);return;}
 if(phase==9&&frames>20){Check(floorHand->actor.scale.x==.007f&&floorHand->collider.dim.radius==17&&floorHand->collider.dim.height==28,"One absorbed sibling grows the native merge master to intermediate scale and collider size");EnFloormas_SetupSmWait(family[2]);Next(10);return;}
 if(phase==10&&frames>65){Check(floorHand->actor.scale.x==.01f&&floorHand->actor.colChkInfo.health==4&&floorHand->actor.params==0&&(floorHand->collider.info.bumperFlags&BUMP_HOOKABLE)&&floorHand->collider.base.colType!=COLTYPE_HARD,"Completed native merge restores full scale, health, hookshot surface and vulnerability");FloorDamage(floorHand,9,4);Check(floorHand->actionFunc==EnFloormas_Freeze&&floorHand->actor.colChkInfo.health==0&&kills==0,"Lethal light effect delays splitting until native freeze ends");Next(11);return;}
 if(phase==11&&floorHand->actionFunc==EnFloormas_Split){Check(kills==0,"Freeze expiry splits without granting a large-hand defeat");Next(12);return;}
 if(phase==12&&frames>45){for(auto* h:family){EnFloormas_MakeVulnerable(h);FloorDamage(h,3,0);}Next(13);return;}
 if(phase==13&&frames>70){Check(!Alive(&family[0]->actor)&&!Alive(&family[1]->actor)&&!Alive(&family[2]->actor)&&kills==3&&gARPGSave.kills==3,"Three small defeats each grant one reward and retire the entire native family");floorHand=nullptr;family={};SpawnFloor(true);gPlayState->actorCtx.lensActive=true;Models(&floorHand->actor,floorHand->skelAnime);Check(floorHand->actor.draw==EnFloormas_DrawHighlighted&&(floorHand->actor.flags&ACTOR_FLAG_REACT_TO_LENS),"Invisible variant retains native Lens visibility and translucent draw callback");EnFloormas_SetupHover(floorHand,gPlayState);Next(14);return;}
 if(phase==14){gPlayState->actorCtx.lensActive=true;if(frames>80){Check(lensFrames>=50,"Lens variant renders through hover, charge and landing with native green fog");Clear();gPlayState->actorCtx.lensActive=false;fixture={anchor.x,anchor.y,anchor.z+500};Camera();SpawnWall(1);Check(wallHand->actionFunc==EnWallmas_WaitForProximity&&!wallHand->actor.draw,"Original proximity Wallmaster remains hidden until approached");Next(15);return;}}
 if(phase==15&&frames>12){Check(wallHand->actionFunc==EnWallmas_WaitForProximity,"Distant player does not start the ceiling ambush");fixture={anchor.x,anchor.y,anchor.z+100};Next(16);return;}
 if(phase==16&&wallHand->actionFunc==EnWallmas_Drop){Check(shadowFrames>70&&wallHand->actor.world.pos.y>fixture.y+200,"Native shadow warning counts down before the three-hundred-unit ceiling drop");Models(&wallHand->actor,wallHand->skelAnime);Vec3f pos{};Vec3s rot{};Gfx* dl=nullptr;EnWallMas_OverrideLimbDraw(gPlayState,1,&dl,&pos,&rot,wallHand);Check(pos.z==-1600,"Original Wallmaster root translation survives the replacement callback");fixture.x+=120;Next(17);return;}
 if(phase==17){wallLanded|=wallHand->actionFunc==EnWallmas_Land;wallWalked|=wallHand->actionFunc==EnWallmas_Walk;wallReturned|=wallHand->actionFunc==EnWallmas_ReturnToCeiling;if(wallReturned&&wallHand->actionFunc==EnWallmas_WaitToDrop){Check(wallLanded&&wallWalked&&dropFrames>5,"Sidestep preserves native miss, landing, walking recovery, ceiling return and rearm");Actor_Kill(&wallHand->actor);wallHand=nullptr;fixture={anchor.x,anchor.y,anchor.z+700};SpawnWall(0);wallHand->actor.world.pos=anchor;EnWallmas_SetupWalk(wallHand);WallDamage(1,0);Check(wallHand->actor.colChkInfo.health==3&&wallHand->actionFunc==EnWallmas_TakeDamage,"Grounded Wallmaster retains original health and damage recoil");Next(18);return;}}
 if(phase==18&&frames>30){Check(wallHand->actionFunc==EnWallmas_Cooldown,"Nonlethal Wallmaster recoil enters the original cooldown animation");WallDamage(0,1);Check(wallHand->actionFunc==EnWallmas_Stun&&wallHand->timer==80,"Wallmaster stun preserves the eighty-frame native window");Next(19);return;}
 if(phase==19&&frames>100){Check(wallHand->actionFunc!=EnWallmas_Stun,"Wallmaster resumes ceiling return after stun expires");Actor_Kill(&wallHand->actor);SpawnWall(0);wallHand->actor.world.pos=anchor;EnWallmas_SetupWalk(wallHand);WallDamage(9,4);Check(wallHand->actionFunc==EnWallmas_Stun&&wallHand->actor.colChkInfo.health==0&&kills==3,"Lethal light stun defers Wallmaster death until the effect completes");Next(20);return;}
 if(phase==20&&frames>110){Check(!Alive(&wallHand->actor)&&kills==4&&gARPGSave.kills==4,"Frozen Wallmaster defeat shrinks away and grants exactly one native and ARPG reward");SpawnWall(0);wallHand->actor.world.pos=anchor;EnWallmas_SetupWalk(wallHand);WallDamage(9,0);Next(21);return;}
 if(phase==21&&frames>70){Check(!Alive(&wallHand->actor)&&kills==5&&gARPGSave.kills==5,"Ordinary Wallmaster defeat retains its single reward");wallHand=nullptr;Check(!Creatures::SpawnHandmasterPractice(gPlayState,-1)&&!Creatures::SpawnHandmasterPractice(gPlayState,2),"Unsupported practice variants cannot create orphan small hands");auto* p=GET_PLAYER(gPlayState);Actor* practice=nullptr;for(int i=0;i<16&&!practice;++i){p->actor.shape.rot.y=i*0x1000;practice=Creatures::SpawnHandmasterPractice(gPlayState,1);}Check(practice&&practice->params==1,"Wallmaster practice uses the native proximity ambush");Clear();SpawnFloor();SpawnFloor();Check(!Creatures::SpawnHandmasterPractice(gPlayState,0)&&!Creatures::SpawnHandmasterPractice(gPlayState,1),"Practice cap counts hidden sibling actors as well as visible hands");Clear();Next(22);return;}
 if(phase==22&&frames>10){Check(kills==5,"Encounter cleanup invents no combat rewards");Warp();Next(24);return;}
 if(phase==24&&frames>100&&gPlayState&&GameInteractor::IsPlayerInControl()){Check(kills==5&&gARPGSave.kills==5,"Scene teardown preserves exactly five earned defeats");if(!visual){phase=99;Write("passed");return;}fixture=GET_PLAYER(gPlayState)->actor.world.pos;anchor={fixture.x,fixture.y,fixture.z+200};fixture.x+=120;Clear();Camera();SpawnFloor();Next(25);return;}
 if(phase==25&&frames>4){Camera();gPlayState->frameAdvCtx.enabled=true;phase=98;Write("passed");}
 if(frames>1000)throw std::runtime_error("Handmaster integration timeout");
 }catch(const std::exception& e){phase=99;if(gPlayState)gPlayState->frameAdvCtx.enabled=true;Write("failed",e.what());}}
void Register(){auto* enabled=std::getenv("SOH_ARPG_HANDMASTER_QA");auto* home=std::getenv("SHIP_HOME");if(!enabled||std::string(enabled)!="1"||!home||!std::filesystem::path(home).filename().string().starts_with("soh-arpg-qa-"))return;output=std::filesystem::path(home)/"handmaster-results.json";visual=std::getenv("SOH_ARPG_HANDMASTER_UI")!=nullptr;
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnGameFrameUpdate>(Tick);
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnEnemyDefeat>([](void* p){auto id=static_cast<Actor*>(p)->id;if(id==ACTOR_EN_FLOORMAS||id==ACTOR_EN_WALLMAS)++kills;});
 GameInteractor::Instance->RegisterGameHook<GameInteractor::OnPlayDrawEnd>([](){if(!gPlayState)return;if(floorHand&&Alive(&floorHand->actor)){++drawFrames;std::array<s16,45> pose{};for(int j=0;j<15;++j){pose[j*3]=floorHand->jointTable[j+3].x;pose[j*3+1]=floorHand->jointTable[j+3].y;pose[j*3+2]=floorHand->jointTable[j+3].z;}fingerAngles.insert(pose);chargeFrames+=floorHand->actionFunc==EnFloormas_Charge;smallFrames+=floorHand->actor.scale.x==.004f;lensFrames+=floorHand->actor.draw==EnFloormas_DrawHighlighted&&gPlayState->actorCtx.lensActive;}if(wallHand&&Alive(&wallHand->actor)){++drawFrames;shadowFrames+=wallHand->actionFunc==EnWallmas_WaitToDrop;dropFrames+=wallHand->actionFunc==EnWallmas_Drop;}});
}
